(()=>{'use strict';const A=RepoAccount,U=RepoAdminUI,slot=document.querySelector('#capture-settings');let epoch=0,settings=null;
const names={screenshotone:'ScreenshotOne',thumio:'Thum.io',cloudflare:'Cloudflare Browser Run'},keys={screenshotone:'SCREENSHOTONE_ACCESS_KEY',thumio:'No key required for its free URL API',cloudflare:'CLOUDFLARE_BROWSER_TOKEN and CLOUDFLARE_ACCOUNT_ID'},limits={screenshotone:'100 requests / UTC month',thumio:'1,000 requests / UTC month',cloudflare:'10 requests / UTC day; 60 seconds reserved per request'};
async function load(){if(!A.user?.admin)return;const token=++epoch;try{const data=await A.request('/api/editorial?action=capture-settings');if(token!==epoch||!A.user?.admin)return;settings=data.settings;slot.innerHTML=`<p class="small">Optional fallback for demos already validated as working. Images await administrator approval. Enable only after creating a free provider account and adding its key in GitHub → Settings → Secrets and variables → Actions. Thum.io’s free URL API needs no key.</p><form id="capture-form">${Object.keys(names).map(id=>`<label class="publish-control"><input type="checkbox" name="${id}" ${settings.providers[id]?'checked':''}> ${names[id]}</label><p class="small">${U.esc(keys[id])} · ${limits[id]}. ${Number((data.usage||[]).find(u=>u.provider===id&&u.period===(id==='cloudflare'?new Date().toISOString().slice(0,10):new Date().toISOString().slice(0,7)+'-01'))?.attempts||0)} attempts used this period. ${data.receipt?data.receipt.ready?.[id]?'Available at the last sync.':'Key missing at the last sync.':'Configuration will be checked at the next sync.'}</p>`).join('')}<button class="button" type="submit">Save screenshot settings</button><p id="capture-message" role="status"></p></form><p class="small">Limits count attempts, including errors, and remain enforced across syncs. Allowances assume dedicated free accounts. Keep provider billing disabled; outside use also consumes provider quotas. API keys are never entered here or stored in the catalogue. Candidate captures are checked for blank images, then reviewed by you before publication.</p>${data.receipt?`<p class="small">Last check: ${U.esc(new Date(data.receipt.at).toLocaleString())}. ${Number(data.receipt.attempted||0)} requests, ${Number(data.receipt.candidates||0)} review candidates.</p>`:''}`;
 document.querySelector('#capture-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button'),message=document.querySelector('#capture-message');button.disabled=true;message.textContent='Saving…';try{await A.request('/api/editorial?action=capture-settings',{method:'POST',body:JSON.stringify({revision:settings.revision,providers:Object.fromEntries(Object.keys(names).map(id=>[id,form.elements[id].checked]))})});await load();document.querySelector('#capture-message').textContent='Saved. The next sync will use enabled, configured providers.'}catch(err){message.textContent=err.message;if(err.status===409)void load()}finally{button.disabled=false}};
 }catch(err){if(token!==epoch)return;slot.innerHTML=err.code==='migration_required'?'<p>Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610050013_capture_providers.sql" target="_blank" rel="noopener">migration 13</a> to enable optional provider settings. Regular screenshots continue without it.</p>':U.errorHtml(err.message,'capture');}}
 document.addEventListener('click',e=>{if(e.target.closest('[data-admin-tab="quality"], [data-retry="capture"]'))void load()});window.addEventListener('reposhelf-account',()=>{epoch++;if(!A.user?.admin){slot.innerHTML='';settings=null}else if(new URL(location.href).searchParams.get('tab')==='quality')void load()});if(A.user?.admin&&new URL(location.href).searchParams.get('tab')==='quality')void load();})();
